"""Generate custom_dialect/include/RvNpu/RvNpuMmio.h from spec/abi.py.

The header gives the compiler (LowerToRiscv, crt0.S) and any C or C++ code the
MMIO window, CVA6's address map, the STATUS fields and the error and DONE
codes as preprocessor constants, so it can be included from C, C++ and
assembly alike. It is checked in; src/test/tests/test_risc_v_npu_abi.py fails
when it differs from this script's output.

    python src/vendors/risc_v_npu/spec/gen_mmio_header.py          # rewrite
    python src/vendors/risc_v_npu/spec/gen_mmio_header.py --check  # compare only
"""

from __future__ import annotations

import argparse
import importlib.util
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
HEADER = HERE.parent / 'custom_dialect' / 'include' / 'RvNpu' / 'RvNpuMmio.h'


def _abi():
    """spec/abi.py, loaded by path so this runs as a script or as a module."""
    spec = importlib.util.spec_from_file_location('_risc_v_npu_abi', HERE / 'abi.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _define(name: str, value: int, comment: str = '') -> str:
    line = f'#define {name:<36} 0x{value:08X}'
    return f'{line}  /* {comment} */' if comment else line


def render() -> str:
    abi = _abi()
    out = [
        '/* RvNpuMmio.h - the CVA6 NPU MMIO window, as seen by a RISC-V program.',
        ' *',
        ' * GENERATED by src/vendors/risc_v_npu/spec/gen_mmio_header.py from',
        ' * src/vendors/risc_v_npu/spec/abi.py. Do not edit; rerun the generator.',
        ' *',
        ' * Plain preprocessor constants: usable from C, C++ and assembly (.S).',
        ' * Registers are 32 bits wide; use single 32-bit volatile accesses.',
        ' */',
        '#ifndef RVNPU_RVNPUMMIO_H',
        '#define RVNPU_RVNPUMMIO_H',
        '',
        '/* Address map seen by CVA6. */',
        _define('RVNPU_MMIO_BASE', abi.MMIO_BASE, 'uncached, non-idempotent'),
        _define('RVNPU_MMIO_BYTES', abi.MMIO_BYTES),
        _define('RVNPU_DDR_BASE', abi.DDR_BASE, 'cached, executable'),
        _define('RVNPU_DDR_BYTES', abi.DDR_BYTES),
        _define('RVNPU_OPERAND_ALIGN', abi.MMIO_OPERAND_ALIGN, 'A, B, C addresses'),
        '',
        '/* Register offsets from RVNPU_MMIO_BASE (access type in the comment). */',
    ]
    for reg in abi.MmioRegister:
        out.append(_define(f'RVNPU_MMIO_{reg.name}', reg.value, abi.MMIO_ACCESS[reg]))
    out += ['', '/* Shape fields. */']
    for name, (reg, shift, width) in abi.MMIO_SHAPE_FIELDS.items():
        out.append(_define(f'RVNPU_SHAPE_{name}_SHIFT', shift, f'in {reg.name}'))
        out.append(_define(f'RVNPU_SHAPE_{name}_MASK', (1 << width) - 1))
    out += ['', '/* STATUS and FENCE fields. */']
    for flag in abi.MmioStatus:
        out.append(_define(f'RVNPU_STATUS_{flag.name}', flag.value))
    for name, (shift, width) in abi.MMIO_STATUS_FIELDS.items():
        out.append(_define(f'RVNPU_STATUS_{name}_SHIFT', shift))
        out.append(_define(f'RVNPU_STATUS_{name}_MASK', (1 << width) - 1))
    shift, width = abi.MMIO_DONE_CODE
    out += ['', '/* DONE. */',
            _define('RVNPU_DONE_CODE_SHIFT', shift),
            _define('RVNPU_DONE_CODE_MASK', (1 << width) - 1)]
    for code in abi.DoneCode:
        out.append(_define(f'RVNPU_DONE_{code.name}', code.value))
    out += ['', '/* Faults the MMIO block latches (STATUS error code, then ISA_ERROR). */']
    for code in abi.MmioError:
        out.append(_define(f'RVNPU_ERR_{code.name}', code.value))
    out += ['', '/* Matrix-core faults, forwarded unchanged. */']
    for code in abi.ErrorCode:
        out.append(_define(f'RVNPU_MATRIX_ERR_{code.name}', code.value))
    out += ['', '#endif /* RVNPU_RVNPUMMIO_H */', '']
    return '\n'.join(out)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true', help='fail if the checked-in header differs')
    args = parser.parse_args()
    text = render()
    if args.check:
        current = HEADER.read_text(encoding='utf-8') if HEADER.exists() else ''
        if current != text:
            print(f'{HEADER} is stale; rerun {Path(__file__).name}', file=sys.stderr)
            return 1
        return 0
    HEADER.parent.mkdir(parents=True, exist_ok=True)
    HEADER.write_text(text, encoding='utf-8', newline='\n')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
